const cancelRef = useRef<HTMLButtonElement>(null);

<Dialog
  open={confirming}
  onClose={() => setConfirming(false)}
  role="alertdialog"
  title="Delete project"
  description="Everything in it goes too."
  size="sm"
  initialFocus={cancelRef}
  footer={
    <>
      <Button ref={cancelRef} variant="secondary" onClick={() => setConfirming(false)}>Cancel</Button>
      <Button variant="destructive" onClick={remove}>Delete</Button>
    </>
  }
>
  This cannot be undone.
</Dialog>

const sections = [
  {
    items: [
      { label: "Invoices", href: "/invoices", current: true },
      { label: "Clients", href: "/clients" },
    ],
  },
];

{/* The media queries are the page's — this system has no breakpoint
    tokens, because where a rail stops fitting depends on the rail. */}
<MobileNav className="narrow-only" title="Ratā" label="Main" sections={sections} />
<SideNav className="wide-only" label="Main" sections={sections} />

{/* The wrapper is always rendered, so the live region exists
    before the notice arrives. Rendering the Notice itself
    conditionally is what makes announcements unreliable. */}
<div aria-live="polite">
  {error ? (
    <Notice variant="danger" title="Could not save" actions={<Button variant="secondary" onClick={retry}>Retry</Button>}>
      {error.message}
    </Notice>
  ) : null}
</div>

{/* `live` stays off and the region sits on the wrapper: the notice is
    mounted at the same moment its text appears, and a live region has
    to pre-exist its content to be announced reliably. */}
<div aria-live="polite">
  {sent ? (
    <Notice
      variant="success"
      onDismiss={() => {
        setSent(false);
        // Dismissing destroys the focused button, so focus has to go
        // somewhere deliberate rather than fall to <body>.
        tableRef.current?.focus();
      }}
    >
      Invitations sent to 12 people.
    </Notice>
  ) : null}
</div>

{/* Don't: three headings over one link each. */}
<SideNav
  sections={[
    { label: "Invoices", items: [{ label: "All invoices", href: "/invoices" }] },
    { label: "Clients", items: [{ label: "All clients", href: "/clients" }] },
  ]}
/>

{/* Don't: this is a choice being made, not a region being revealed. */}
<Tabs
  label="Billing period"
  items={[
    { value: "monthly", label: "Monthly", content: null },
    { value: "annual", label: "Annual", content: null },
  ]}
/>

{/* Don't: "New invoice" is not a place. */}
<TopNav
  items={[
    { label: "Invoices", href: "/invoices" },
    { label: "New invoice", href: "#", current: false },
  ]}
/>
